package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Grade;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.setting.SheetParentRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class RateService {

    private final RateRepository rates;
    private final RateChangeRepository changes;
    private final SheetService sheets;
    private final SheetParentRepository parents;
    private final Rollup rollup;
    private final Audit audit;

    public RateService(RateRepository rates, RateChangeRepository changes, SheetService sheets,
            SheetParentRepository parents, Rollup rollup, Audit audit) {
        this.rates = rates;
        this.changes = changes;
        this.sheets = sheets;
        this.parents = parents;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's rates in grade order, then by from-date; a grade with no rate is left out. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdInOrder(sheetId);
    }

    /** A rate of the sheet or of one of its parents, with how many levels up it is (0: the sheet's own). */
    public record Inherited(int level, Rate rate) {
    }

    /** The rates of the sheet and of its parents up to three levels up, nearest first, each in grade order,
     *  then by from-date. */
    @Transactional(readOnly = true)
    public List<Inherited> listInherited(String sheetId) {
        List<Inherited> all = new ArrayList<>();
        List<String> lineage = SettingService.lineageOf(parents, sheetId);
        for (int level = 0; level < lineage.size(); level++) {
            for (Rate rate : rates.findBySheetIdInOrder(lineage.get(level))) all.add(new Inherited(level, rate));
        }
        return all;
    }

    /** The grade's rate in force on a date: of the sheet's rates, the one with the latest from-date on or
     *  before it, unless the date is after that rate's to-date; when none is, the parent's in force then, and
     *  so on up to three levels up; null when none is. */
    @Transactional(readOnly = true)
    public Rate inForce(String sheetId, Grade grade, LocalDate date) {
        List<List<Rate>> levels = new ArrayList<>();
        for (String id : SettingService.lineageOf(parents, sheetId)) levels.add(rates.findForGrade(id, grade));
        return Rate.inForceInherited(levels, date);
    }

    /** The grade's rate in force on a date as the sheet's rates stood at the end of another date (asOf):
     *  every setting made while the sheet's today was on or before it counts, every later one does not;
     *  null when none is in force then. */
    @Transactional(readOnly = true)
    public Rate inForceAsOf(String sheetId, Grade grade, LocalDate date, LocalDate asOf) {
        // The parents are those the sheet names now, each read as its rates stood at the end of the same date.
        for (String id : SettingService.lineageOf(parents, sheetId)) {
            Rate rate = ownInForceAsOf(id, grade, date, asOf);
            if (rate != null) return rate;
        }
        return null;
    }

    private Rate ownInForceAsOf(String sheetId, Grade grade, LocalDate date, LocalDate asOf) {
        Map<LocalDate, Rate> byFrom = new HashMap<>();
        Rate fromStart = null;
        for (RateChange change : changes.findBySheetIdOrderByIdAsc(sheetId)) {
            if (change.getGrade() != grade || !change.madeBy(asOf)) continue;
            if (change.getFrom() == null) fromStart = change.toRate();
            else byFrom.put(change.getFrom(), change.toRate());
        }
        List<Rate> gradeRates = new ArrayList<>();
        if (fromStart != null) gradeRates.add(fromStart);
        byFrom.keySet().stream().sorted().forEach((from) -> gradeRates.add(byFrom.get(from)));
        return Rate.inForce(gradeRates, date);
    }

    /** Set the sheet's rate for a grade from a from-date (none: from the beginning of time) through
     *  a to-date (none: until the grade's next rate), replacing the rate it had for that from-date. A
     *  to-date before the from-date is refused. */
    @Transactional
    public Rate set(String sheetId, String user, Grade grade, LocalDate from, LocalDate to, BigDecimal pct) {
        if (from != null && to != null && to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date.");
        }
        sheets.load(sheetId);
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        Rate rate = (from == null ? rates.findFromStart(sheetId, grade) : rates.findFrom(sheetId, grade, from))
                .orElse(null);
        if (rate == null) {
            rate = new Rate(sheetId, grade, from, to, pct);
        } else {
            rate.setPct(pct);
            rate.setTo(to);
        }
        Rate saved;
        try {
            saved = rates.saveAndFlush(rate);
            changes.saveAndFlush(new RateChange(saved, sheets.today(sheetId)));
        } catch (DataIntegrityViolationException raced) {
            // Another user set the same grade's rate for that from-date at the same moment.
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The rate was changed by someone else.");
        }
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + saved.getGrade()
                + " rate=" + saved.getPct().toPlainString() + (from == null ? "" : " from=" + from)
                + (to == null ? "" : " to=" + to));
        rollup.recordChanges(user, before);
        return saved;
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Grade;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /** What the screen shows of a rate; the percent always has two decimals. No from-date means the
     *  rate applies from the beginning of time; no to-date, until the grade's next rate. Level is how many
     *  parents up the rate's sheet is: 0 for the sheet's own, 1 for its parent's, and so on. */
    public record RateView(Grade grade, String pct, LocalDate from, LocalDate to, int level) {
        static RateView of(Rate rate) {
            return of(0, rate);
        }

        static RateView of(int level, Rate rate) {
            return new RateView(rate.getGrade(), rate.getPct().toPlainString(), rate.getFrom(), rate.getTo(), level);
        }
    }

    /** A rate's percent, from-date and to-date, as entered on the form; no from-date means from the
     *  beginning of time, no to-date until the grade's next rate. */
    public record RateForm(@NotNull @DecimalMin("0.00") @Digits(integer = 3, fraction = 2) BigDecimal pct,
            LocalDate from, LocalDate to) {
    }

    /** What a candidate rate would do: how many claims would show a different due, and the sum of
     *  the differences with two decimals. */
    public record PreviewView(int count, String diff) {
    }

    private final RateService service;
    private final ClaimService claims;

    public RateController(RateService service, ClaimService claims) {
        this.service = service;
        this.claims = claims;
    }

    /** Preview a candidate percent for a grade on every date against the sheet's OPEN and PENDING
     *  claims; nothing is saved and nothing is audited. */
    @GetMapping("/{grade}/preview")
    public PreviewView preview(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable Grade grade,
            @RequestParam @NotNull @DecimalMin("0.00") @Digits(integer = 3, fraction = 2) BigDecimal pct) {
        ClaimService.RatePreview preview = claims.previewRate(sheetId.trim(), grade, pct);
        return new PreviewView(preview.count(), preview.diff().toPlainString());
    }

    /** The sheet's rates in grade order, then by from-date, followed by its parents' up to three levels up,
     *  nearest first; a grade with no rate is left out. */
    @GetMapping
    public List<RateView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.listInherited(sheetId.trim()).stream().map((r) -> RateView.of(r.level(), r.rate())).toList();
    }

    /** Set the rate for a grade from a from-date through a to-date, replacing the one it had for that from-date. */
    @PutMapping("/{grade}")
    public RateView set(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable Grade grade,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid RateForm form) {
        return RateView.of(service.set(sheetId.trim(), SignedInUser.name(user), grade, form.from(), form.to(), form.pct()));
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Grade } from '../people/people-api';

export interface RateView {
  grade: Grade;
  /** The percent with two decimals, as the store holds it. */
  pct: string;
  /** The date the rate is in force from (yyyy-mm-dd), or null when it applies from the beginning of time. */
  from: string | null;
  /** The last date the rate is in force (yyyy-mm-dd), or null when it runs until the grade's next rate. */
  to: string | null;
  /** How many parents up the rate's sheet is: 0 for the sheet's own rate, 1 for its parent's, and so on. */
  level: number;
}

/** Of one grade's rates on one sheet, the one in force on a date: the one with the latest from-date on
 *  or before it, or null when the date is before every one of them or after that one's to-date. */
function ownRateInForce(rates: readonly RateView[], date: string): RateView | null {
  let inForce: RateView | null = null;
  for (const r of rates) {
    if (r.from !== null && r.from > date) continue;
    if (inForce === null || (inForce.from ?? '') < (r.from ?? '')) inForce = r;
  }
  return inForce !== null && inForce.to !== null && inForce.to < date ? null : inForce;
}

/** Of one grade's rates, the one in force on a date: the sheet's own, else the nearest parent's in
 *  force then; null when none is. */
export function rateInForce(rates: readonly RateView[], date: string): RateView | null {
  const levels = [...new Set(rates.map((r) => r.level ?? 0))].sort((a, b) => a - b);
  for (const level of levels) {
    const rate = ownRateInForce(rates.filter((r) => (r.level ?? 0) === level), date);
    if (rate !== null) return rate;
  }
  return null;
}

/** Whether two rates are the same sheet's rate of the same grade for the same from-date. */
export function sameRate(a: RateView, b: RateView): boolean {
  return a.grade === b.grade && a.from === b.from && a.level === b.level;
}

/** What is due on an amount of `amountCents` at a rate of `pct` percent, in whole cents: the
 *  amount times the rate, divided by 100, rounded half to even (a half rounds to the even cent), or
 *  half up (a half rounds away from zero) when `halfUp`. */
export function dueCents(amountCents: number, pct: string, halfUp = false): number {
  // Hundredths of a percent, so the product is exact; cents x basis points / 10000 = due cents.
  const product = BigInt(amountCents) * BigInt(Math.round(Number(pct) * 100));
  const sign = product < 0n ? -1n : 1n;
  const magnitude = sign * product;
  let whole = magnitude / 10000n;
  const rest = magnitude % 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n))) whole += 1n;
  return Number(whole * sign);
}

/** What a candidate rate would do: how many claims would show a different due, and the sum of the
 *  differences (new due less current due) with two decimals. */
export interface RatePreview {
  count: number;
  diff: string;
}

// The sheet's rates per grade, as the store holds them.
@Injectable({ providedIn: 'root' })
export class RatesApi {
  private readonly http = inject(HttpClient);

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }

  /** The sheet's rates, then its parents' up to three levels up (by level); a grade with no rate is left out. */
  list(sheetId: string): Promise<RateView[]> {
    return firstValueFrom(this.http.get<RateView[]>(this.url(sheetId)));
  }

  /** Set the grade's rate from a from-date (null: from the beginning of time) through a to-date
   *  (null: until the grade's next rate), replacing the one it had for that from-date. */
  set(sheetId: string, grade: Grade, pct: string, from: string | null, to: string | null): Promise<RateView> {
    return firstValueFrom(this.http.put<RateView>(`${this.url(sheetId)}/${grade}`, { pct, from, to }));
  }

  /** Preview the grade's candidate percent on every date; nothing is saved. */
  preview(sheetId: string, grade: Grade, pct: string): Promise<RatePreview> {
    return firstValueFrom(this.http.get<RatePreview>(`${this.url(sheetId)}/${grade}/preview`, { params: { pct } }));
  }
}
