package net.officefloor.hq.app.paste;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PasteClaimsService {

    /** A pasted line, read: the person it names and the claim's fields (no date: the sheet's entry date,
     *  else its today; no ref: no reference). */
    private record Line(Person person, BigDecimal amount, LocalDate date, String note, String ref) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final ClaimService claimService;

    public PasteClaimsService(PersonRepository people, ClaimRepository claims, ClaimService claimService) {
        this.people = people;
        this.claims = claims;
        this.claimService = claimService;
    }

    /** Add a draft claim per pasted line of name,amount,date,note, in order. Every line is read first,
     *  then each is added with the claim form's rules; one change: when any line is refused, nothing is
     *  added and nothing is written. Blank lines are skipped; a paste with no lines is refused, as is one
     *  giving a reference already used on the sheet or by an earlier line, compared without regard to case. */
    @Transactional
    public List<Claim> paste(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        int number = 0;
        for (String raw : text.split("\\r?\\n")) {
            number++;
            if (raw.isBlank()) continue;
            Line line = read(sheetId, raw, number);
            if (line.ref() != null && (!refs.add(line.ref().toLowerCase(Locale.ROOT))
                    || claims.refUsed(sheetId, line.ref(), null))) {
                throw refused(number, "the reference '" + line.ref() + "' is already used");
            }
            lines.add(line);
        }
        if (lines.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Paste at least one line.");
        }
        List<Claim> added = new ArrayList<>();
        for (Line line : lines) {
            added.add(claimService.add(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note(), null,
                    line.ref(), null));
        }
        return added;
    }

    /** A line of name,amount,date,note; the note may hold commas, the date may be blank and the note absent.
     *  A note ending in ' #<reference>' gives the claim that reference, which is not part of the note. */
    private Line read(String sheetId, String raw, int number) {
        String[] fields = raw.split(",", 4);
        if (fields.length < 2) throw refused(number, "it needs at least a name and an amount");
        String name = fields[0].trim();
        Person person = name.isEmpty() ? null
                : people.findByNameOrAlias(sheetId, Person.keyOf(name)).orElse(null);
        if (person == null) throw refused(number, "no one on the sheet is named '" + name + "'");
        BigDecimal amount;
        try {
            amount = new BigDecimal(fields[1].trim());
        } catch (NumberFormatException e) {
            throw refused(number, "the amount is not a number");
        }
        if (amount.scale() > 2 || amount.precision() - amount.scale() > 10) {
            throw refused(number, "the amount has more than two decimals or ten digits");
        }
        LocalDate date = null;
        if (fields.length > 2 && !fields[2].isBlank()) {
            try {
                date = LocalDate.parse(fields[2].trim());
            } catch (DateTimeParseException e) {
                throw refused(number, "the date is not a date (yyyy-mm-dd)");
            }
        }
        String note = fields.length > 3 ? fields[3].trim() : "";
        String ref = null;
        int hash = note.lastIndexOf(" #");
        if (hash >= 0) {
            ref = ClaimService.refOf(note.substring(hash + 2));
            note = note.substring(0, hash).trim();
        }
        if (ref != null && ref.length() > 220) throw refused(number, "the reference is longer than 220 characters");
        if (note.length() > 1000) throw refused(number, "the note is longer than 1000 characters");
        return new Line(person, amount, date, note, ref);
    }

    private static ResponseStatusException refused(int number, String why) {
        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Line " + number + ": " + why + ".");
    }
}
package net.officefloor.hq.app;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.Set;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.server.ResponseStatusException;

/**
 * Refuses every change a viewer of a sheet asks for: any request on a sheet other than reading it
 * (a GET, or loading the sheet) is refused before it reaches its controller, so it writes nothing.
 * The bulk changes are let through: a viewer's bulk change is answered with every selected claim
 * refused (see {@code BulkChangeService}), and a viewer's bulk grade with no one changed (see
 * {@code BulkGradeService}).
 */
@Component
public class ViewerGuard implements HandlerInterceptor {

    /** The path of a sheet's requests; the sheet id is the segment after it. */
    public static final String SHEETS = "/api/sheets/";

    static final Set<String> LET_THROUGH = Set.of("load", "claims/open", "claims/settle", "claims/reassign", "people/grade");

    private final SettingService settings;

    public ViewerGuard(SettingService settings) {
        this.settings = settings;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod())) return true;
        String path = request.getRequestURI().substring(request.getContextPath().length());
        String header = request.getHeader(SignedInUser.HEADER);
        if (!path.startsWith(SHEETS) || header == null || header.isBlank()) return true;
        String rest = path.substring(SHEETS.length());
        int slash = rest.indexOf('/');
        if (slash < 0 || LET_THROUGH.contains(rest.substring(slash + 1))) return true;
        String sheetId = URLDecoder.decode(rest.substring(0, slash), StandardCharsets.UTF_8).trim();
        if (settings.roleOf(sheetId, SignedInUser.name(header)) == Role.VIEWER) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer cannot change anything.");
        }
        return true;
    }
}
package net.officefloor.hq.app;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.server.ResponseStatusException;

/**
 * Refuses every change asked for on an archived sheet: any request on a sheet other than reading it
 * (a GET, or loading the sheet) is refused before it reaches its controller, so it writes nothing.
 * As for a viewer, the bulk changes are let through and answered with every selected claim refused
 * (see {@code BulkChangeService}), and the bulk grade with no one changed (see {@code BulkGradeService}).
 */
@Component
public class ArchiveGuard implements HandlerInterceptor {

    private final SheetRepository sheets;

    public ArchiveGuard(SheetRepository sheets) {
        this.sheets = sheets;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod())) return true;
        String path = request.getRequestURI().substring(request.getContextPath().length());
        if (!path.startsWith(ViewerGuard.SHEETS)) return true;
        String rest = path.substring(ViewerGuard.SHEETS.length());
        int slash = rest.indexOf('/');
        if (slash < 0 || ViewerGuard.LET_THROUGH.contains(rest.substring(slash + 1))) return true;
        String sheetId = URLDecoder.decode(rest.substring(0, slash), StandardCharsets.UTF_8).trim();
        if (sheets.isArchived(sheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived: nothing on it can be changed.");
        }
        return true;
    }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { ClaimView, ClaimsApi } from './claims-api';

// A box that takes lines of name,amount,date,note and adds a draft claim per line, in order, to the
// named people; every line is checked first, and when any is refused nothing is added.
@Component({
  selector: 'app-paste-claims',
  imports: [ReactiveFormsModule],
  template: `
    <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Paste claims">
      <label for="paste-claims">Paste claims, one per line: name,amount,date,note</label>
      <textarea id="paste-claims" data-testid="paste-claims" formControlName="text" rows="4"></textarea>
      <button type="submit" data-testid="paste-submit" [disabled]="saving()">Add pasted claims</button>
      @if (count() !== null) {
        <p>Added: <strong data-testid="paste-added">{{ count() }}</strong></p>
      }
      @if (error()) {
        <p role="alert" data-testid="paste-error">{{ error() }}</p>
      }
    </form>
  `,
})
export class PasteClaims {
  private readonly session = inject(Session);
  private readonly api = inject(ClaimsApi);

  readonly added = output<ClaimView[]>();

  protected readonly form = new FormGroup({
    text: new FormControl('', { nonNullable: true }),
  });
  protected readonly saving = signal(false);
  protected readonly error = signal('');
  protected readonly count = signal<number | null>(null);

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    // Each load of a sheet starts the box afresh.
    effect(() => {
      this.session.loaded();
      this.error.set('');
      this.count.set(null);
      this.form.reset({ text: '' }, { emitEvent: false });
    });
  }

  protected async submit(): Promise<void> {
    if (this.saving()) return;
    const sheet = this.session.sheet();
    if (!sheet) return;
    this.error.set('');
    this.count.set(null);
    const text = this.form.getRawValue().text;
    if (!text.trim()) {
      this.error.set('Paste at least one line of name,amount,date,note.');
      return;
    }
    this.saving.set(true);
    try {
      const result = await this.api.paste(sheet.id, text);
      if (this.session.sheet()?.id === sheet.id) {
        this.count.set(result.added);
        this.added.emit(result.claims);
      }
    } catch (e) {
      if (this.session.sheet()?.id !== sheet.id) return;
      const reason = e instanceof HttpErrorResponse && typeof e.error?.message === 'string' && e.error.message
        ? ' ' + e.error.message : '';
      this.error.set('No claims were added: a line was refused.' + reason);
    } finally {
      this.saving.set(false);
    }
  }
}
